import com.super_awesome_baby.ares_hud.compat.AresHudCompatManager;
import de.teamlapen.vampirism.api.VampirismAPI;
import de.teamlapen.vampirism.api.client.VIngameOverlays;
import de.teamlapen.vampirism.api.entity.player.vampire.IBloodStats;
import de.teamlapen.vampirism.util.Helper;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;

public final class VampirismCompat {
    private VampirismCompat() {
    }

    public static AresHudCompatManager.VampirismBloodData getBloodData(Player player) {
        if (!AresHudCompatManager.isVampirismLoaded || player == null || !Helper.isVampire((Player)player)) {
            return AresHudCompatManager.NO_VAMPIRISM_BLOOD;
        }
        return VampirismAPI.getVampirePlayer((Player)player).resolve().map(vampirePlayer -> {
            IBloodStats bloodStats = vampirePlayer.getBloodStats();
            return new AresHudCompatManager.VampirismBloodData(true, bloodStats.getBloodLevel(), bloodStats.getMaxBlood(), bloodStats.getPrevBloodLevel());
        }).orElse(AresHudCompatManager.NO_VAMPIRISM_BLOOD);
    }

    public static boolean isBloodBarOverlay(ResourceLocation overlayId) {
        return VIngameOverlays.BLOOD_BAR_ID.equals((Object)overlayId);
    }
}

