    @SafeVarargs
    public CompatMod(String modid, Function<AbstractCompatMod, CompatMixinInfo> ... mixinClasses) {
        this.modid = modid;
        for (Function<AbstractCompatMod, CompatMixinInfo> mixinClass : mixinClasses) {
            mixinClass.apply(this);
        }
    }

