    VAMPIRISM_BLOOD;


    public static FoodSlotContent resolve(boolean tcrLoaded, boolean standaloneArmorEnabled, boolean overrideSpellBarsEnabled, boolean replaceFoodWithMana, boolean manaVisible, boolean vampirismBloodVisible) {
        if (vampirismBloodVisible) {
            return VAMPIRISM_BLOOD;
