        if (standaloneArmorEnabled || !overrideSpellBarsEnabled) {
            return FOOD;
        }
        return replaceFoodWithMana && manaVisible ? MANA : FOOD;
    }

    public boolean usesFoodValue() {
        return this != MANA;
    }

