    if (AresHudCompatManager.hasMultipleStaminaSources() && BarType.fromStaminaSource(configured = HudConfig.LAYOUT_DATA.get((Object)((Object)t)).staminaSource).isAvailable()) {
        return configured;
    }
    if (AresHudCompatManager.isParcoolLoaded) {
