    public void initializeConditionBindings(Set<String> previousSources, Map<String, List<Rule>> defaults) {
        if (this.conditionBindings != null) {
            return;
        }
        this.conditionBindings = new ConditionBindings();
        this.conditionBindings.sources.addAll(previousSources);
        this.conditionBindings.localSources.addAll(previousSources);
        for (String source : previousSources) {
            boolean customizedThreshold;
            List<Rule> existing = this.conditions.stream().filter(rule -> rule.source().equals(source)).toList();
            List expected = defaults.getOrDefault(source, List.of());
            boolean bl = customizedThreshold = this.lowThresholds.containsKey(source) || this.changeThresholds.keySet().stream().anyMatch(key -> key.startsWith(source + "/"));
            if (!customizedThreshold && !expected.isEmpty() && new LinkedHashSet<Rule>(existing).equals(new LinkedHashSet(expected))) {
                this.conditionBindings.generated.addAll(existing);
