public static void initialize() {
    if (initialized) {
        HudPresetManager.restoreBuiltins();
        HudPresetManager.apply(HudPresetManager.active());
        return;
    }
    if (!ExternalHudConfig.canSave()) {
        lastError = "ares_hud-external.json";
        return;
    }
    HotbarType selected = HudConfig.getHotbarType();
    for (HotbarType type : HotbarType.values()) {
        Preset preset = new Preset();
        preset.id = HudPresetManager.builtinId(type);
        preset.name = type.name();
        preset.baseStyle = type;
        preset.layout = HudConfig.capturePresetLayout(type);
        preset.layers = ExternalHudConfig.copyLayers(type);
        preset.display = ExternalHudConfig.copyDisplays(type);
        PRESETS.put(preset.id, preset);
    }
    HudPresetManager.scan();
    for (HotbarType type : HotbarType.values()) {
        String id2 = HudPresetManager.dynamicBuiltinId(type);
        if (PRESETS.containsKey(id2) || BLOCKED.contains(id2)) continue;
        Preset dynamic = (Preset)GSON.fromJson(GSON.toJson((Object)PRESETS.get(HudPresetManager.builtinId(type))), Preset.class);
