public LayoutConfigData(ForgeConfigSpec.Builder builder, HotbarType type) {
    this.type = type;
    this.barSlots = LayoutConfigData.defaultBarSlots(type);
    this.finalityHotbarLayout = FinalityHotbarLayout.defaultFor(type);
    String prefix = type.getConfigPrefix();
    HotbarType defaultHotbarVisualType = type.isFinality() ? this.finalityHotbarLayout.visualType() : type;
    HudRelativeBounds defaultHotbarBounds = type.isFinality() ? this.finalityHotbarLayout.defaultHotbarBounds(type) : defaultHotbarVisualType.defHotbar;
    HudRelativeBounds defaultOffhandBounds = type.isFinality() ? this.finalityHotbarLayout.defaultOffhandBounds(type) : defaultHotbarVisualType.defOffhand;
    builder.push("Layout_" + type.name());
    this.specHotbarBounds = builder.define("hotbar" + prefix + "Properties", (Object)defaultHotbarBounds.toString(), RELATIVE_BOUNDS_VALIDATOR);
    this.specOffhandBounds = builder.define("offhand" + prefix + "Properties", (Object)defaultOffhandBounds.toString(), RELATIVE_BOUNDS_VALIDATOR);
    this.specCenterBounds = builder.define("centerHud" + prefix + "Properties", (Object)type.defCenterHud.toString(), RELATIVE_BOUNDS_VALIDATOR);
    this.specBossBarBounds = builder.define("bossBar" + prefix + "Properties", (Object)DEFAULT_BOSS_BAR_BOUNDS.toString(), RELATIVE_BOUNDS_VALIDATOR);
    this.specFinalityHotbarLayout = type.isFinality() ? builder.defineEnum("finalityHotbarLayout", (Enum)this.finalityHotbarLayout) : null;
    this.specCenterHudLayoutMode = builder.defineEnum("centerHudLayoutMode", (Enum)CenterHudLayoutMode.MERGED);
    this.specSeparateCenterHudInitialized = builder.define("separateCenterHudInitialized", false);
    this.specSeparateAuxiliaryHudInitialized = builder.define("separateAuxiliaryHudInitialized", false);
    this.specCenterSlotBounds = new ForgeConfigSpec.ConfigValue[BarSlot.values().length];
    HudRelativeBounds[] defaultSlotBounds = LayoutConfigData.createCenterSlotBounds(type.defCenterHud, type.defPaddingHoriz, type.defPaddingVert, this.barSlots);
    for (BarSlot slot : BarSlot.values()) {
        this.specCenterSlotBounds[slot.ordinal()] = builder.define("centerHudSlot" + slot.name() + "Properties", (Object)defaultSlotBounds[slot.ordinal()].toString(), RELATIVE_BOUNDS_VALIDATOR);
