import com.super_awesome_baby.ares_hud.compat.PeakStaminaCompat;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.RegisterGuiOverlaysEvent;
import net.minecraftforge.client.gui.overlay.VanillaGuiOverlay;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.ModList;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid="ares_hud", bus=Mod.EventBusSubscriber.Bus.MOD, value={Dist.CLIENT})
public class ClientModEvents {
    @SubscribeEvent
    public static void registerGuiOverlays(RegisterGuiOverlaysEvent event) {
        ExternalHudManager.registerBuiltIn(BuffHudLayer.BENEFICIAL_ID);
        ExternalHudManager.registerBuiltIn(BuffHudLayer.DETRIMENTAL_ID);
        ExternalHudManager.registerBuiltIn(SelectedItemNameHud.ID);
        if (ModList.get().isLoaded("peakstamina")) {
            event.registerAbove(VanillaGuiOverlay.EXPERIENCE_BAR.id(), "peak_stamina", (gui, graphics, partialTick, width, height) -> PeakStaminaCompat.renderNativeHud(graphics));
        }
        event.registerBelow(VanillaGuiOverlay.CHAT_PANEL.id(), "ares_hud", AresHudOverlay.ARES_HUD);
        if (FoodBagCooldownHud.installed()) {
            ExternalHudManager.registerBuiltIn(FoodBagCooldownHud.ID);
            event.registerBelow(VanillaGuiOverlay.CHAT_PANEL.id(), "food_bag_cooldown", (gui, graphics, partialTick, width, height) -> FoodBagCooldownHud.render(graphics, partialTick));
        }
        event.registerBelow(VanillaGuiOverlay.CHAT_PANEL.id(), "tough_as_nails_thirst", ToughAsNailsThirstOverlay.OVERLAY);
    }
}

